// Function to convert UYVY to [Y, U, V] array and fill input_image
float (*convert_uyvy_to_yuv_array(struct image_t *img))[240][520][3];
float (*convert_uyvy_to_yuv_array(struct image_t *img))[240][520][3] {
  int width = img->w;
  int height = img->h;

  //printf("Image width: %d, height: %d\n", width, height);

  if (width != 240 || height != 520) { // New expected image size is [240][520] after rotation
      printf("Error: Image size must be [240][520] (images are rotated 90 degrees)\n");
      return NULL;
  }

  // Allocate memory for the tensor (1 batch, 240 height, 520 width, 3 channels)
  float (*yuv_array)[240][520][3] = 
      (float(*)[240][520][3])malloc(1 * height * width * 3 * sizeof(float));

  if (!yuv_array) {
      printf("Error: Memory allocation failed\n");
      return NULL;
  }

  uint8_t *data = (uint8_t *)img->buf;
  // int index = 0;

  // Now that the image is rotated, we read it as if width is 240 and height is 520
  for (int y = 0; y < height; y++) {
      for (int x = 0; x < width; x += 2) {
          int pixel_index = (y * width + x) * 2;
          
          float U  = (float)data[pixel_index];     // U for both pixels
          float Y1 = (float)data[pixel_index + 1]; // Y for pixel 1
          float V  = (float)data[pixel_index + 2]; // V for both pixels
          float Y2 = (float)data[pixel_index + 3]; // Y for pixel 2

          // uint8_t U  = data[pixel_index];     // U for both pixels
          // uint8_t Y1 = data[pixel_index + 1]; // Y for pixel 1
          // uint8_t V  = data[pixel_index + 2]; // V for both pixels
          // uint8_t Y2 = data[pixel_index + 3]; // Y for pixel 2

          // // Normalize values to [0, 1] range
          // float norm_Y1 = Y1 / 255.0f;
          // float norm_U  = U / 255.0f;
          // float norm_V  = V / 255.0f;
          // float norm_Y2 = Y2 / 255.0f;

          // Store first pixel in the tensor
          yuv_array[0][x][y][0] = Y1; // Y
          yuv_array[0][x][y][1] = U;  // U
          yuv_array[0][x][y][2] = V;  // V

          // Store second pixel in the tensor
          if (x + 1 < width) {
              yuv_array[0][x + 1][y][0] = Y2; // Y
              yuv_array[0][x + 1][y][1] = U;  // U
              yuv_array[0][x + 1][y][2] = V;  // V
          }
      }
  }

  // Debugging output (optional):
  // printf("First 10 pixels in YUV format:\n");
  // for (int i = 0; i < 10; i++) {
  //     int row = i / height;
  //     int col = i % height;
  //     printf("Pixel [%d][%d]: Y = %.3f, U = %.3f, V = %.3f\n", row, col,
  //            yuv_array[0][col][row][0], yuv_array[0][col][row][1], yuv_array[0][col][row][2]);
  // }

  return yuv_array;
}


// Function
uint32_t find_object_centroid(struct image_t *img, int32_t* p_xc, int32_t* p_yc, bool draw,
                              uint8_t lum_min, uint8_t lum_max,
                              uint8_t cb_min, uint8_t cb_max,
                              uint8_t cr_min, uint8_t cr_max);

/*
 * object_detector
 * @param img - input image to process
 * @param filter - which detection filter to process
 * @return img
 */
static struct image_t *object_detector(struct image_t *img, uint8_t filter)
{
  // printf("------------------------------------\n");
  float (*yuv_array)[240][520][3] = convert_uyvy_to_yuv_array(img);
  // printf("------------------------------------\n");

  pthread_mutex_lock(&output_mutex);
  if (yuv_array) {
    //printf("Running model inference...\n");
    model_inference_processed(yuv_array, ouput_array_cut);
    free(yuv_array);
  }
  // for (int i = 0; i < 64; i++) {
  //   printf("output_array_cut[%d] = %f\n", i, ouput_array_cut[i]);
  // }
  pthread_mutex_unlock(&output_mutex);

  uint8_t lum_min, lum_max;
  uint8_t cb_min, cb_max;
  uint8_t cr_min, cr_max;
  bool draw;

  switch (filter){
    case 1:
      lum_min = cod_lum_min1;
      lum_max = cod_lum_max1;
      cb_min = cod_cb_min1;
      cb_max = cod_cb_max1;
      cr_min = cod_cr_min1;
      cr_max = cod_cr_max1;
      draw = cod_draw1;
      break;
    case 2:
      lum_min = cod_lum_min2;
      lum_max = cod_lum_max2;
      cb_min = cod_cb_min2;
      cb_max = cod_cb_max2;
      cr_min = cod_cr_min2;
      cr_max = cod_cr_max2;
      draw = cod_draw2;
      break;
    default:
      return img;
  };

  int32_t x_c, y_c;

  // Filter and find centroid
  uint32_t count = find_object_centroid(img, &x_c, &y_c, draw, lum_min, lum_max, cb_min, cb_max, cr_min, cr_max);
  VERBOSE_PRINT("Color count %d: %u, threshold %u, x_c %d, y_c %d\n", camera, object_count, count_threshold, x_c, y_c);
  VERBOSE_PRINT("centroid %d: (%d, %d) r: %4.2f a: %4.2f\n", camera, x_c, y_c,
        hypotf(x_c, y_c) / hypotf(img->w * 0.5, img->h * 0.5), RadOfDeg(atan2f(y_c, x_c)));

  pthread_mutex_lock(&mutex);
  global_filters[filter-1].color_count = count;
  global_filters[filter-1].x_c = x_c;
  global_filters[filter-1].y_c = y_c;
  global_filters[filter-1].updated = true;
  pthread_mutex_unlock(&mutex);

  return img;
}

struct image_t *object_detector1(struct image_t *img, uint8_t camera_id);
struct image_t *object_detector1(struct image_t *img, uint8_t camera_id __attribute__((unused)))
{
  return object_detector(img, 1);
}

struct image_t *object_detector2(struct image_t *img, uint8_t camera_id);
struct image_t *object_detector2(struct image_t *img, uint8_t camera_id __attribute__((unused)))
{
  return object_detector(img, 2);
}

void color_object_detector_init(void)
{
  memset(global_filters, 0, 2*sizeof(struct color_object_t));
  pthread_mutex_init(&mutex, NULL);
  pthread_mutex_init(&output_mutex, NULL);
#ifdef COLOR_OBJECT_DETECTOR_CAMERA1
#ifdef COLOR_OBJECT_DETECTOR_LUM_MIN1
  cod_lum_min1 = COLOR_OBJECT_DETECTOR_LUM_MIN1;
  cod_lum_max1 = COLOR_OBJECT_DETECTOR_LUM_MAX1;
  cod_cb_min1 = COLOR_OBJECT_DETECTOR_CB_MIN1;
  cod_cb_max1 = COLOR_OBJECT_DETECTOR_CB_MAX1;
  cod_cr_min1 = COLOR_OBJECT_DETECTOR_CR_MIN1;
  cod_cr_max1 = COLOR_OBJECT_DETECTOR_CR_MAX1;
#endif
#ifdef COLOR_OBJECT_DETECTOR_DRAW1
  cod_draw1 = COLOR_OBJECT_DETECTOR_DRAW1;
#endif

  cv_add_to_device(&COLOR_OBJECT_DETECTOR_CAMERA1, object_detector1, COLOR_OBJECT_DETECTOR_FPS1, 0);
#endif

#ifdef COLOR_OBJECT_DETECTOR_CAMERA2
#ifdef COLOR_OBJECT_DETECTOR_LUM_MIN2
  cod_lum_min2 = COLOR_OBJECT_DETECTOR_LUM_MIN2;
  cod_lum_max2 = COLOR_OBJECT_DETECTOR_LUM_MAX2;
  cod_cb_min2 = COLOR_OBJECT_DETECTOR_CB_MIN2;
  cod_cb_max2 = COLOR_OBJECT_DETECTOR_CB_MAX2;
  cod_cr_min2 = COLOR_OBJECT_DETECTOR_CR_MIN2;
  cod_cr_max2 = COLOR_OBJECT_DETECTOR_CR_MAX2;
#endif
#ifdef COLOR_OBJECT_DETECTOR_DRAW2
  cod_draw2 = COLOR_OBJECT_DETECTOR_DRAW2;
#endif

  cv_add_to_device(&COLOR_OBJECT_DETECTOR_CAMERA2, object_detector2, COLOR_OBJECT_DETECTOR_FPS2, 1);
#endif
}

/*
 * find_object_centroid
 *
 * Finds the centroid of pixels in an image within filter bounds.
 * Also returns the amount of pixels that satisfy these filter bounds.
 *
 * @param img - input image to process formatted as YUV422.
 * @param p_xc - x coordinate of the centroid of color object
 * @param p_yc - y coordinate of the centroid of color object
 * @param lum_min - minimum y value for the filter in YCbCr colorspace
 * @param lum_max - maximum y value for the filter in YCbCr colorspace
 * @param cb_min - minimum cb value for the filter in YCbCr colorspace
 * @param cb_max - maximum cb value for the filter in YCbCr colorspace
 * @param cr_min - minimum cr value for the filter in YCbCr colorspace
 * @param cr_max - maximum cr value for the filter in YCbCr colorspace
 * @param draw - whether or not to draw on image
 * @return number of pixels of image within the filter bounds.
 */
uint32_t find_object_centroid(struct image_t *img, int32_t* p_xc, int32_t* p_yc, bool draw,
                              uint8_t lum_min, uint8_t lum_max,
                              uint8_t cb_min, uint8_t cb_max,
                              uint8_t cr_min, uint8_t cr_max)
{
  uint32_t cnt = 0;
  uint32_t tot_x = 0;
  uint32_t tot_y = 0;
  uint8_t *buffer = img->buf;

  // Go through all the pixels
  for (uint16_t y = 0; y < img->h; y++) {
    for (uint16_t x = 0; x < img->w; x ++) {
      // Check if the color is inside the specified values
      uint8_t *yp, *up, *vp;
      if (x % 2 == 0) {
        // Even x
        up = &buffer[y * 2 * img->w + 2 * x];      // U
        yp = &buffer[y * 2 * img->w + 2 * x + 1];  // Y1
        vp = &buffer[y * 2 * img->w + 2 * x + 2];  // V
        //yp = &buffer[y * 2 * img->w + 2 * x + 3]; // Y2
      } else {
        // Uneven x
        up = &buffer[y * 2 * img->w + 2 * x - 2];  // U
        //yp = &buffer[y * 2 * img->w + 2 * x - 1]; // Y1
        vp = &buffer[y * 2 * img->w + 2 * x];      // V
        yp = &buffer[y * 2 * img->w + 2 * x + 1];  // Y2
      }
      if ( (*yp >= lum_min) && (*yp <= lum_max) &&
           (*up >= cb_min ) && (*up <= cb_max ) &&
           (*vp >= cr_min ) && (*vp <= cr_max )) {
        cnt ++;
        tot_x += x;
        tot_y += y;
        if (draw){
          *yp = 255;  // make pixel brighter in image
        }
      }
    }
  }
  if (cnt > 0) {
    *p_xc = (int32_t)roundf(tot_x / ((float) cnt) - img->w * 0.5f);
    *p_yc = (int32_t)roundf(img->h * 0.5f - tot_y / ((float) cnt));
  } else {
    *p_xc = 0;
    *p_yc = 0;
  }
  return cnt;
}

void color_object_detector_periodic(void)
{
  static struct color_object_t local_filters[2];
  pthread_mutex_lock(&mutex);
  memcpy(local_filters, global_filters, 2*sizeof(struct color_object_t));
  pthread_mutex_unlock(&mutex);

  if(local_filters[0].updated){
    AbiSendMsgVISUAL_DETECTION(COLOR_OBJECT_DETECTION1_ID, local_filters[0].x_c, local_filters[0].y_c,
        0, 0, local_filters[0].color_count, 0);
    local_filters[0].updated = false;
  }
  if(local_filters[1].updated){
    AbiSendMsgVISUAL_DETECTION(COLOR_OBJECT_DETECTION2_ID, local_filters[1].x_c, local_filters[1].y_c,
        0, 0, local_filters[1].color_count, 1);
    local_filters[1].updated = false;
  }

  float local_output[384];
  pthread_mutex_lock(&output_mutex);
  memcpy(local_output, ouput_array_cut, 384 * sizeof(float));
  pthread_mutex_unlock(&output_mutex);

  AbiSendMsgTENSOR_OUTPUT(TENSOR_OUTPUT_id, local_output);
}


